// Init Analytics — run context + typed config (viral_config). Missing keys fall back to DEFAULTS.

const DEFAULTS = {
  ig_user_id: '',
  ig_api_version: 'v23.0',
  analytics_track_days: 7,
  yt_channel_handle: '@viralstreamersdaily',
  fb_page_id: '',
  fb_api_version: 'v23.0',
  ig_reel_metrics: 'views,reach,likes,comments,shares,saved,total_interactions,ig_reels_avg_watch_time,ig_reels_video_view_total_time',
};

const config = { ...DEFAULTS };
for (const item of $input.all()) {
  const r = item.json;
  const key = String(r.key ?? '').trim();
  if (!(key in DEFAULTS)) continue;
  const hasNum = r.value_number !== null && r.value_number !== undefined && Number.isFinite(Number(r.value_number));
  const hasStr = typeof r.value_string === 'string' && r.value_string.trim() !== '';
  if (typeof DEFAULTS[key] === 'number') { if (hasNum) config[key] = Number(r.value_number); }
  else if (hasStr) config[key] = r.value_string.trim();
}
config.ig_reel_metrics = config.ig_reel_metrics.split(',').map(s => s.trim()).filter(Boolean).join(',');

return [{
  json: {
    run_id: `ana-${$now.toFormat('yyyyMMdd-HHmm')}-${$execution.id}`,
    started_at: new Date().toISOString(),
    graph: `https://graph.instagram.com/${config.ig_api_version}`,
    config,
  },
}];

// Map Metrics — one snapshot row per Reel from its insights response.
// Values come as data[].values[0].value (or total_value.value); missing metrics stay null.

const run = $('Init Analytics').first().json;
const posts = $('Get Published').all();
const num = v => (v === undefined || v === null || !Number.isFinite(Number(v)) ? null : Number(v));
const nowIso = new Date().toISOString();

return $input.all().map((it, i) => {
  const post = posts[i]?.json ?? {};
  const res = it.json ?? {};
  const m = {};
  for (const d of res.data ?? []) m[d.name] = num(d.values?.[0]?.value ?? d.total_value?.value);
  const ageH = (Date.now() - Date.parse(post.published_at)) / 3.6e6;
  return {
    json: {
      post_key: post.post_key,
      ig_media_id: post.ig_media_id,
      source_key: post.source_key,
      captured_at: nowIso,
      age_h: Number.isFinite(ageH) ? Math.round(ageH * 10) / 10 : null,
      views: m.views ?? null,
      reach: m.reach ?? null,
      likes: m.likes ?? null,
      comments: m.comments ?? null,
      shares: m.shares ?? null,
      saved: m.saved ?? null,
      total_interactions: m.total_interactions ?? null,
      avg_watch_ms: m.ig_reels_avg_watch_time ?? null,
      total_watch_ms: m.ig_reels_video_view_total_time ?? null,
      run_id: run.run_id,
      error: res.error ? String(res.error.message ?? res.error).slice(0, 300) : '',
    },
  };
});

// Build Run Log — one row for viral_runs: Reels measured and insights errors of this run.

const run = $('Init Analytics').first().json;
const rows = $('Map Metrics').all().map(i => i.json);
const errors = rows.filter(r => r.error).map(r => `${r.post_key}: ${r.error}`);
const account = $('Account Info').first().json;
if (account.error) errors.push(`account: ${String(account.error.message ?? account.error).slice(0, 200)}`);

return [{
  json: {
    run_id: run.run_id,
    workflow: '04 - US VIRAL | Analytics',
    started_at: run.started_at,
    finished_at: new Date().toISOString(),
    status: errors.length ? 'PARTIAL' : 'SUCCESS',
    videos_fetched: rows.length,
    errors: JSON.stringify({ errors, followers: account.followers_count ?? null }).slice(0, 4000),
  },
}];

// YT Build Request — the YouTube Shorts of the Reels published in the last analytics_track_days.
// yt_video_id is set by 06 (YouTube Publisher) or by hand after a manual upload; anything that is not an
// 11-char YouTube id (e.g. empty) is skipped. One videos.list call takes up to 50 ids.

const posts = $input.all()
  .map(i => i.json ?? {})
  .filter(p => /^[A-Za-z0-9_-]{11}$/.test(String(p.yt_video_id ?? '').trim()))
  .slice(0, 50)
  .map(p => ({ post_key: p.post_key, yt_video_id: String(p.yt_video_id).trim(), source_key: p.source_key,
    published_at: p.yt_published_at || p.published_at }));
if (!posts.length) return [];
return [{ json: { ids: posts.map(p => p.yt_video_id).join(','), posts } }];

// Map YT Metrics — one snapshot row per Short found by YouTube (deleted / private ones are simply missing).

const run = $('Init Analytics').first().json;
const posts = $('YT Build Request').first().json.posts;
const stats = new Map(($input.first().json.items ?? []).map(v => [v.id, v.statistics ?? {}]));
const num = v => (v === undefined || v === null || !Number.isFinite(Number(v)) ? null : Number(v));
const nowIso = new Date().toISOString();

return posts.filter(p => stats.has(p.yt_video_id)).map(p => {
  const s = stats.get(p.yt_video_id);
  const ageH = (Date.now() - Date.parse(p.published_at)) / 3.6e6;
  return {
    json: {
      post_key: p.post_key,
      platform: 'youtube',
      platform_video_id: p.yt_video_id,
      source_key: p.source_key,
      captured_at: nowIso,
      age_h: Number.isFinite(ageH) ? Math.round(ageH * 10) / 10 : null,
      views: num(s.viewCount),
      likes: num(s.likeCount),
      comments: num(s.commentCount),
      run_id: run.run_id,
    },
  };
});

// YT Match Uploads — links the Shorts uploaded by hand to their Reel, so nobody has to fill yt_video_id.
// A Reel without yt_video_id gets the latest upload of our channel that (1) is not linked to another Reel,
// (2) went up between 12h before and 72h after the Instagram post, and (3) mentions the meme line, the first
// line of the caption (often used as title), the hook or the streamer. Best text match wins, then the closest in time.
// Output: every post of Get Published (with the linked yt_video_id), link_new = true for the new links.

const posts = $('Get Published').all().map(i => ({ ...(i.json ?? {}) }));
const uploads = ($input.first().json.items ?? []).map(it => ({
  id: it.snippet?.resourceId?.videoId ?? it.contentDetails?.videoId,
  at: Date.parse(it.contentDetails?.videoPublishedAt ?? it.snippet?.publishedAt ?? ''),
  text: `${it.snippet?.title ?? ''} ${it.snippet?.description ?? ''}`,
})).filter(u => u.id && Number.isFinite(u.at));

const isYtId = v => /^[A-Za-z0-9_-]{11}$/.test(String(v ?? '').trim());
const norm = s => String(s ?? '').toLowerCase().normalize('NFKD').replace(/[^a-z0-9]+/g, ' ').trim();
const used = new Set(posts.filter(p => isYtId(p.yt_video_id)).map(p => String(p.yt_video_id).trim()));

const score = (p, u) => {
  const t = ` ${norm(u.text)} `;
  let s = 0;
  const fields = { meme_caption: 3, caption_head: 3, hook: 2, title: 1 };
  const vals = { ...p, caption_head: String(p.caption ?? '').split('\n')[0] };
  for (const [field, w] of Object.entries(fields)) {
    const v = norm(vals[field]);
    if (v.length >= 6 && t.includes(` ${v} `)) s = Math.max(s, w);
  }
  const creator = norm(p.creator_name);
  if (creator && t.includes(` ${creator} `)) s += 1;
  return s;
};

for (const p of posts.sort((a, b) => Date.parse(a.published_at) - Date.parse(b.published_at))) {
  if (isYtId(p.yt_video_id)) continue;
  const pub = Date.parse(p.published_at);
  if (!Number.isFinite(pub)) continue;
  const best = uploads
    .filter(u => !used.has(u.id) && u.at >= pub - 12 * 3.6e6 && u.at <= pub + 72 * 3.6e6)
    .map(u => ({ u, s: score(p, u), d: Math.abs(u.at - pub) }))
    .filter(x => x.s > 0)
    .sort((a, b) => b.s - a.s || a.d - b.d)[0];
  if (!best) continue;
  used.add(best.u.id);
  p.yt_video_id = best.u.id;
  p.yt_published_at = new Date(best.u.at).toISOString();
  p.link_new = true;
}

return posts.map(p => ({ json: p }));

// FB Match Reels — links the Reels shared on the Page by hand (fb_video_id empty or "manual") to their post, from
// the Page's latest Reels: not linked to another post, up 12h before to 72h after the Instagram post, and the
// description mentions the caption's first line, the meme line or the streamer. Then one item per post with a
// Facebook video id (for the insights); link_new = true for the new links.

const posts = $('Get Published').all().map(i => ({ ...(i.json ?? {}) }));
const reels = ($input.first().json.data ?? []).map(r => ({
  id: String(r.id ?? ''), at: Date.parse(r.created_time ?? ''), text: String(r.description ?? ''),
})).filter(r => /^\d+$/.test(r.id) && Number.isFinite(r.at));

const isFbId = v => /^\d+$/.test(String(v ?? '').trim());
const norm = s => String(s ?? '').toLowerCase().normalize('NFKD').replace(/[^a-z0-9]+/g, ' ').trim();
const used = new Set(posts.filter(p => isFbId(p.fb_video_id)).map(p => String(p.fb_video_id).trim()));
const score = (p, r) => {
  const t = ` ${norm(r.text)} `;
  let s = 0;
  for (const v of [String(p.caption ?? '').split('\n')[0], p.meme_caption, p.hook]) {
    const n = norm(v);
    if (n.length >= 6 && t.includes(` ${n} `)) s = Math.max(s, 3);
  }
  const c = norm(p.creator_name);
  if (c && t.includes(` ${c} `)) s += 1;
  return s;
};

for (const p of posts.sort((a, b) => Date.parse(a.published_at) - Date.parse(b.published_at))) {
  if (isFbId(p.fb_video_id)) continue;
  const pub = Date.parse(p.published_at);
  if (!Number.isFinite(pub)) continue;
  const best = reels
    .filter(r => !used.has(r.id) && r.at >= pub - 12 * 3.6e6 && r.at <= pub + 72 * 3.6e6)
    .map(r => ({ r, s: score(p, r), d: Math.abs(r.at - pub) }))
    .filter(x => x.s > 0)
    .sort((a, b) => b.s - a.s || a.d - b.d)[0];
  if (!best) continue;
  used.add(best.r.id);
  p.fb_video_id = best.r.id;
  p.fb_published_at = new Date(best.r.at).toISOString();
  p.link_new = true;
}

return posts.filter(p => isFbId(p.fb_video_id)).map(p => ({ json: {
  post_key: p.post_key, source_key: p.source_key, fb_video_id: String(p.fb_video_id).trim(),
  published_at: p.fb_published_at || p.published_at, link_new: p.link_new === true,
} }));

// Map FB Metrics — one snapshot row per Facebook Reel from video_insights (lifetime values).
// Values can be numbers or objects (reactions by type, actions by type): objects are summed.

const run = $('Init Analytics').first().json;
const items = $('FB Match Reels').all();
const sum = v => (v && typeof v === 'object' ? Object.values(v).reduce((a, b) => a + (Number(b) || 0), 0)
  : (Number.isFinite(Number(v)) ? Number(v) : null));
const nowIso = new Date().toISOString();

return $input.all().map((it, i) => {
  const post = items[i]?.json ?? {};
  const res = it.json ?? {};
  const m = {};
  for (const d of res.data ?? []) m[d.name] = d.values?.[0]?.value;
  const actions = m.post_video_social_actions && typeof m.post_video_social_actions === 'object' ? m.post_video_social_actions : {};
  const ageH = (Date.now() - Date.parse(post.published_at)) / 3.6e6;
  return { json: {
    post_key: post.post_key, platform: 'facebook', platform_video_id: post.fb_video_id, source_key: post.source_key,
    captured_at: nowIso, age_h: Number.isFinite(ageH) ? Math.round(ageH * 10) / 10 : null,
    views: sum(m.fb_reels_total_plays ?? m.blue_reels_play_count),
    reach: sum(m.blue_reels_play_count),  // plays without replays (Facebook has no reach metric for Reels)
    likes: sum(m.post_video_likes_by_reaction_type),
    comments: sum(actions.COMMENT ?? actions.comment ?? 0),
    shares: sum(actions.SHARE ?? actions.share ?? 0),
    avg_watch_ms: sum(m.post_video_avg_time_watched),
    total_watch_ms: sum(m.post_video_view_time),
    run_id: run.run_id,
    error: res.error ? String(res.error.message ?? res.error).slice(0, 300) : '',
  } };
});
